<script setup>
import { computed, onScopeDispose, reactive, ref, watch } from 'vue'
import axios from 'axios'
import MailTemplatesDialog from '@/Components/Contacts/Emails/MailTemplatesDialog.vue'

const props = defineProps({ unitId: { type: [Number, String], default: null }, orderId: { type: [Number, String], default: null }, recipients: { type: Array, default: () => [] }, mailboxes: { type: Array, default: () => [] }, unitFiles: { type: Array, default: () => [] }, initialTo: { type: Array, default: () => [] }, initialStorageFiles: { type: Array, default: () => [] } })
const emit = defineEmits(['close', 'saved', 'sent', 'state'])
const document = ref(null), context = ref(null), form = reactive({}), contextTab = ref('assortment'), search = ref(''), warehouseFilter = ref(null), includeDeferred = ref(false), deliveryTo = ref('')
const loading = ref(false), contextLoading = ref(false), saving = ref(false), sending = ref(false), previewLoading = ref(false), reconciling = ref(false)
const error = ref(''), contextError = ref(''), notice = ref(''), previewHtml = ref(''), previewOpen = ref(false), baseline = ref(''), closeConfirmation = ref(false)
const contextQuantities = reactive({}), expanded = reactive({}), availableMailboxes = ref([]), localFiles = ref([]), storageFiles = ref([]), fileInput = ref(null)
const templates = ref([]), templateId = ref(''), templatesLoading = ref(false), templatesDialog = ref(false)
let generation = 0, contextVersion = 0, previewVersion = 0, searchTimer = null
const initialized = ref(false), statusUncertain = ref(false), loadFailed = ref(false)
const clone = value => JSON.parse(JSON.stringify(value))
const uid = () => crypto.randomUUID()
const numeric = value => value === '' || value == null ? null : Number(value)
const addresses = value => [...new Set(String(value || '').split(/[;,\n]+/).map(item => item.trim()).filter(Boolean))]
const money = value => value == null ? '—' : Number(value).toLocaleString('ru-RU', { maximumFractionDigits: 6 })
const message = failure => Object.values(failure.response?.data?.errors || {}).flat().join(' ') || failure.response?.data?.message || 'Не удалось выполнить действие. Повторите попытку.'
const busy = computed(() => loading.value || saving.value || sending.value || reconciling.value)
const editable = computed(() => !loadFailed.value && !statusUncertain.value && (!document.value || (document.value.editable ?? document.value.status === 'draft')))
const locked = computed(() => busy.value || !editable.value)
const mailboxItems = computed(() => props.mailboxes.length ? props.mailboxes : availableMailboxes.value)
const recipientItems = computed(() => [...props.recipients, ...(context.value?.recipients || [])].filter(item => item?.address).filter((item, index, items) => items.findIndex(other => other.address.toLowerCase() === item.address.toLowerCase()) === index))
const fileItems = computed(() => [...props.unitFiles.map(file => ({ path: file.path, name: file.name || file.path })), ...props.initialStorageFiles.map(path => ({ path, name: path }))].filter(item => item.path).filter((item, index, items) => items.findIndex(other => other.path === item.path) === index))
const currentUnitId = computed(() => form.unit_id || props.unitId)
const totals = computed(() => {
    const result = {}
    for (const item of form.items || []) if (item.unit_price !== '' && item.unit_price != null && item.quantity) { const code = item.currency_code || (item.currency_id ? `Валюта #${item.currency_id}` : 'Валюта не указана'); result[code] = (result[code] || 0) + Number(item.unit_price) * Number(item.quantity) }
    return result
})
function payload() {
    return { create_key: form.create_key, supplier_order_id: document.value?.id, revision: document.value?.revision, unit_id: Number(form.unit_id || props.unitId), warehouse_id: Number(form.warehouse_id) > 0 ? Number(form.warehouse_id) : null, delivery_date: form.delivery_date || null, subject: form.subject || '', body: form.body || '', mailbox: form.mailbox || null, to: addresses(form.to), cc: addresses(form.cc), include_prices: true, internal_note: form.internal_note || '', items: (form.items || []).map(item => ({ good_id: item.good_id, quantity: numeric(item.quantity), measurement: item.measurement, unit_price: numeric(item.unit_price), currency_id: numeric(item.currency_id), quotation_id: numeric(item.quotation_id), note: item.note || '', source_order_item_ids: item.source_order_item_ids || [] })) }
}
const dirty = computed(() => initialized.value && JSON.stringify(payload()) !== baseline.value)
const unsaved = computed(() => dirty.value || localFiles.value.length > 0 || storageFiles.value.length > 0)
const canSend = computed(() => editable.value && context.value?.can_send === true && !busy.value && (form.items?.length || 0) > 0 && addresses(form.to).length > 0 && addresses(form.to).length <= 5 && addresses(form.cc).length <= 5 && Boolean(form.mailbox) && Boolean(form.subject?.trim()))
function initialForm() {
    return { create_key: uid(), unit_id: Number(props.unitId) || null, warehouse_id: null, delivery_date: '', subject: 'Заказ поставщику', body: 'Добрый день!\nПросим подтвердить наличие, цены и срок поставки указанных товаров.', mailbox: mailboxItems.value[0]?.address || '', to: props.initialTo.map(item => typeof item === 'string' ? item : item?.address || item?.email).filter(Boolean).join(', '), cc: '', include_prices: true, internal_note: '', items: [] }
}
function acceptDocument(value) {
    document.value = value; statusUncertain.value = false
    Object.assign(form, { create_key: value.create_key || form.create_key || uid(), unit_id: value.unit_id || value.unit?.id || form.unit_id, warehouse_id: value.warehouse_id || null, delivery_date: String(value.delivery_date || '').slice(0, 10), subject: value.subject || '', body: value.body || '', mailbox: value.mailbox || '', to: (value.to || []).join(', '), cc: (value.cc || []).join(', '), include_prices: true, internal_note: value.internal_note || '', items: (value.items || []).map(item => ({ ...item, name: item.name || item.good_name || item.good?.name || `Товар #${item.good_id}`, measurement: clone(item.measurement || {}), unit_price: item.unit_price ?? '', currency_id: item.currency_id ?? null, currency_code: item.currency_code || item.currency?.code || '', note: item.note || '' })) })
    baseline.value = JSON.stringify(payload())
}
async function initialize() {
    const version = ++generation
    initialized.value = false; contextLoading.value = false; statusUncertain.value = false; loadFailed.value = false; loading.value = true; error.value = ''; notice.value = ''; context.value = null; document.value = null; previewHtml.value = ''; previewOpen.value = false; closeConfirmation.value = false
    localFiles.value = []; storageFiles.value = [...props.initialStorageFiles]; contextTab.value = 'assortment'; search.value = ''; includeDeferred.value = false; warehouseFilter.value = null
    Object.keys(expanded).forEach(key => delete expanded[key]); Object.keys(contextQuantities).forEach(key => delete contextQuantities[key]); Object.assign(form, initialForm())
    try {
        if (props.orderId) {
            const response = await axios.get(`/api/supplier-orders/${props.orderId}`)
            if (version !== generation) return
            acceptDocument(response.data); warehouseFilter.value = form.warehouse_id ?? 0
        }
        await Promise.allSettled([loadContext(1, version), fetchMailboxes(version)])
        if (version !== generation) return
        baseline.value = JSON.stringify(payload()); initialized.value = true
    } catch (failure) { if (version === generation) { loadFailed.value = true; error.value = message(failure) } }
    finally { if (version === generation) loading.value = false }
}
async function fetchMailboxes(version = generation) {
    if (props.mailboxes.length) return
    try {
        const response = await axios.get('/api/mailboxes')
        if (version !== generation) return
        availableMailboxes.value = response.data.data || response.data || []
        if (!form.mailbox && !document.value) form.mailbox = mailboxItems.value[0]?.address || ''
    } catch (failure) { if (version === generation) error.value = `Почтовые ящики: ${message(failure)}` }
}
async function loadContext(page = 1, good = generation) {
    if (!currentUnitId.value) return
    const version = ++contextVersion, unit = currentUnitId.value
    contextLoading.value = true; contextError.value = ''
    try {
        const response = await axios.get(`/api/units/${unit}/supplier-order-context`, { params: { tab: contextTab.value, search: search.value, warehouse_id: warehouseFilter.value ?? undefined, include_deferred: includeDeferred.value ? 1 : 0, delivery_to: deliveryTo.value || undefined, page, per_page: 30 } })
        if (version !== contextVersion || good !== generation) return
        context.value = response.data
        if (warehouseFilter.value == null) { warehouseFilter.value = response.data.warehouse_id ?? 0; if (!document.value) form.warehouse_id = Number(warehouseFilter.value) > 0 ? Number(warehouseFilter.value) : null }
    } catch (failure) { if (version === contextVersion && good === generation) contextError.value = message(failure) }
    finally { if (version === contextVersion && good === generation) contextLoading.value = false }
}
function searchContext() { clearTimeout(searchTimer); searchTimer = setTimeout(() => loadContext(), 300) }
function selectTab(value) { contextTab.value = value; loadContext() }
function selectedQuantity(good) { return Number((form.items || []).find(item => Number(item.good_id) === Number(good.good_id))?.quantity || 0) }
function recommendedQuantity(good) { return good.to_order_quantity == null ? null : Math.max(0, Number(good.to_order_quantity) - selectedQuantity(good)) }
function addGood(good, quantity = contextQuantities[good.good_id]) {
    if (locked.value) return
    const amount = numeric(quantity)
    if (!Number.isFinite(amount) || amount <= 0) { contextError.value = 'Укажите положительное количество товара. Если остаток или потребность неизвестны, количество нужно задать вручную.'; return }
    const existing = form.items.find(item => Number(item.good_id) === Number(good.good_id))
    if (existing && (Number(existing.measurement?.measure_id) !== Number(good.measurement?.measure_id) || existing.measurement?.unit_label !== good.measurement?.unit_label || Number(existing.measurement?.kilograms_per_unit) !== Number(good.measurement?.kilograms_per_unit))) { contextError.value = 'Единица или масса этого товара изменилась. Удалите старую строку из черновика и добавьте товар заново с проверенным количеством.'; return }
    if (existing) existing.quantity = Math.round((Number(existing.quantity || 0) + amount) * 1000000) / 1000000
    else form.items.push({ good_id: good.good_id, name: good.name, quantity: amount, measurement: clone(good.measurement || {}), unit_price: good.unit_price ?? '', currency_id: good.currency_id ?? null, currency_code: good.currency_code || '', quotation_id: good.quotation_id || null, quotation_snapshot: good.quotation_snapshot ? clone(good.quotation_snapshot) : null, note: '', source_order_item_ids: (good.customer_orders || []).map(item => item.item_id).filter(Boolean) })
    contextQuantities[good.good_id] = ''; contextError.value = ''; notice.value = `${good.name}: добавлено ${money(amount)} ${good.measurement?.unit_label || 'ед.'}`
}
function detachQuotation(item) { item.quotation_id = null; item.quotation_snapshot = null }
function vatLabel(item) { return item.quotation_snapshot?.vat_label || 'НДС не указан' }
function addRecipient(address) { form.to = [...new Set([...addresses(form.to), address])].join(', ') }
function addFiles(event) {
    for (const file of Array.from(event.target.files || [])) if (!localFiles.value.some(item => item.name === file.name && item.size === file.size && item.lastModified === file.lastModified)) localFiles.value.push(file)
    if (fileInput.value) fileInput.value.value = ''
}
async function persist() {
    const version = generation, content = payload()
    saving.value = true; error.value = ''; notice.value = ''
    try {
        const response = document.value?.id ? await axios.patch(`/api/supplier-orders/${document.value.id}`, content) : await axios.post('/api/supplier-orders', content)
        if (version !== generation) return null
        acceptDocument(response.data); emit('saved', response.data); notice.value = `Черновик ${response.data.number || `№${response.data.id}`} сохранён.`
        return response.data
    } catch (failure) { if (version === generation) error.value = message(failure); return null }
    finally { if (version === generation) saving.value = false }
}
async function saveDraft() { if (busy.value || !editable.value) return; return persist() }
async function send() {
    if (!canSend.value) return
    const version = generation
    sending.value = true; error.value = ''; notice.value = ''
    try {
        if (dirty.value || !document.value?.id) { const saved = await persist(); if (!saved || version !== generation) return }
        const content = new FormData(); content.append('revision', document.value.revision)
        localFiles.value.forEach(file => content.append('attachments[]', file)); storageFiles.value.forEach(path => content.append('storage_files[]', path))
        const response = await axios.post(`/api/supplier-orders/${document.value.id}/send`, content)
        if (version !== generation) return
        const value = response.data.order || response.data
        acceptDocument(value)
        if (value.status === 'sent') { localFiles.value = []; storageFiles.value = []; notice.value = response.data.message || `Заказ ${value.number} отправлен поставщику.`; emit('sent', value); loadContext() }
        else error.value = response.data.warning || response.data.message || 'Статус отправки пока не подтверждён. Проверьте его перед повторной отправкой.'
    } catch (failure) {
        if (version !== generation) return
        if (failure.response?.data?.order) acceptDocument(failure.response.data.order)
        else {
            statusUncertain.value = true
            try { const response = await axios.get(`/api/supplier-orders/${document.value.id}`); if (version === generation) acceptDocument(response.data) }
            catch { if (version === generation) error.value = 'Не удалось проверить состояние заказа после ошибки отправки. Повторная отправка заблокирована; проверьте статус.' }
        }
        if (version === generation) error.value = statusUncertain.value ? error.value : message(failure)
    } finally { if (version === generation) sending.value = false }
}
async function reconcile() {
    if (busy.value || !document.value?.id) return
    const version = generation; reconciling.value = true; error.value = ''
    try {
        const response = statusUncertain.value ? await axios.get(`/api/supplier-orders/${document.value.id}`) : await axios.post(`/api/supplier-orders/${document.value.id}/reconcile`, { revision: document.value.revision })
        if (version !== generation) return
        const value = response.data.order || response.data; acceptDocument(value)
        if (value.status === 'sent') { localFiles.value = []; storageFiles.value = []; notice.value = 'Отправка подтверждена.'; emit('sent', value); loadContext() }
        else if (value.status === 'draft') notice.value = 'На сервере сохранён черновик. Отправка доступна после проверки получателей и состава.'
        else error.value = response.data.warning || response.data.message || 'Отправка ещё не подтверждена. Повторная отправка заблокирована.'
    } catch (failure) { if (version === generation) error.value = message(failure) }
    finally { if (version === generation) reconciling.value = false }
}
async function fetchPreview() {
    const version = ++previewVersion, good = generation
    previewOpen.value = true; previewLoading.value = true; error.value = ''
    try {
        const response = !editable.value && document.value?.id ? await axios.get(`/api/supplier-orders/${document.value.id}/preview`) : await axios.post('/api/supplier-orders/preview', payload())
        if (version === previewVersion && good === generation) previewHtml.value = response.data.html || ''
    } catch (failure) { if (version === previewVersion && good === generation) error.value = message(failure) }
    finally { if (version === previewVersion && good === generation) previewLoading.value = false }
}
async function fetchTemplates() {
    if (templatesLoading.value) return
    const version = generation; templatesLoading.value = true
    try { const response = await axios.get('/api/mail-templates'); if (version === generation) templates.value = (response.data || []).filter(item => item.is_active !== false) }
    catch (failure) { if (version === generation) error.value = message(failure) }
    finally { if (version === generation) templatesLoading.value = false }
}
function applyTemplate() { const template = templates.value.find(item => String(item.id) === String(templateId.value)); if (template) { form.subject = template.subject || form.subject; form.body = template.body || form.body } }
function requestClose() { if (busy.value) return; if (unsaved.value) closeConfirmation.value = true; else emit('close') }
function discard() { if (!busy.value) emit('close') }
watch(form, () => { previewVersion++; previewHtml.value = ''; previewLoading.value = false }, { deep: true, flush: 'sync' })
watch([unsaved, busy], ([dirty, busy]) => emit('state', { dirty, busy }))
watch(() => [props.unitId, props.orderId], initialize, { immediate: true })
onScopeDispose(() => { generation++; contextVersion++; previewVersion++; clearTimeout(searchTimer) })
defineExpose({ requestClose })
</script>

<template>
    <section class="supplier-composer" aria-label="Заказ поставщику">
        <header class="composer-heading"><div><h2>{{ document?.number ? `Заказ ${document.number}` : 'Новый заказ поставщику' }} <span>{{ document?.status_label || 'Черновик' }}</span></h2><p>{{ document?.unit?.name || context?.unit?.name || 'Поставщик' }} · {{ dirty ? 'Есть несохранённые изменения' : document ? 'Изменения сохранены' : 'Соберите товары и сохраните черновик' }}</p></div><button class="close-button" :disabled="busy" aria-label="Закрыть заказ поставщику" @click="requestClose">×</button></header>
        <div v-if="closeConfirmation" class="confirmation"><span>Закрыть с несохранёнными изменениями? Локальные вложения сохраняются только при отправке.</span><button :disabled="busy" @click="closeConfirmation = false">Продолжить работу</button><button class="danger" :disabled="busy" @click="discard">Закрыть без сохранения</button></div>
        <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" class="notice" role="status">{{ notice }}</p>
        <p v-if="loadFailed" class="error"><button :disabled="busy" @click="initialize">Повторить загрузку заказа</button></p><p v-if="loading" class="empty" role="status">Загрузка заказа…</p>
        <template v-else>
            <div v-if="document && !editable" class="readonly-notice"><span>Заказ {{ document.status_label || document.status }}. Состав и письмо доступны для просмотра.</span><button v-if="statusUncertain || ['sending', 'send_unknown'].includes(document.status)" :disabled="busy" @click="reconcile">{{ reconciling ? 'Проверяем…' : 'Проверить статус отправки' }}</button></div>
            <div class="composer-layout">
                <main class="letter-pane">
                    <div class="pane-title"><strong>Письмо и состав заказа</strong><span>Письмо отправляется только кнопкой «Отправить заказ»</span></div>
                    <div class="mail-fields">
                        <label>От<select v-model="form.mailbox" :disabled="locked" aria-label="Почтовый ящик"><option value="">Выберите ящик</option><option v-for="mailbox in mailboxItems" :key="mailbox.address" :value="mailbox.address">{{ mailbox.label || mailbox.address }}</option></select></label>
                        <label>Кому · до 5 адресов<input v-model="form.to" :disabled="locked" :list="`supplier-recipients-${currentUnitId}`" placeholder="email@company.ru, второй адрес" aria-label="Получатели заказа"></label>
                        <label>Копия · до 5 адресов<input v-model="form.cc" :disabled="locked" placeholder="Адреса через запятую" aria-label="Копия письма"></label>
                        <datalist :id="`supplier-recipients-${currentUnitId}`"><option v-for="recipient in recipientItems" :key="recipient.address" :value="recipient.address">{{ recipient.name }}</option></datalist>
                        <div v-if="recipientItems.length && editable" class="recipient-shortcuts"><span>Контакты:</span><button v-for="recipient in recipientItems" :key="recipient.address" :disabled="locked" :title="recipient.name || recipient.address" @click="addRecipient(recipient.address)">＋ {{ recipient.address }}</button></div>
                        <label class="wide">Тема<input v-model="form.subject" :disabled="locked" maxlength="255" aria-label="Тема заказа"></label>
                        <div class="delivery-fields"><label>Поставка к<input v-model="form.delivery_date" :disabled="locked" type="date"></label><label>Склад назначения<select v-model="form.warehouse_id" :disabled="locked"><option :value="null">Не указан</option><option v-for="warehouse in context?.warehouses || []" :key="warehouse.id" :value="warehouse.id">{{ warehouse.name }}</option></select></label><span class="price-policy">Закупочные цены и суммы включены в письмо</span></div>
                        <label class="wide">Текст письма<textarea v-model="form.body" :disabled="locked" rows="3" aria-label="Текст письма поставщику"></textarea></label>
                        <details class="mail-tools"><summary>Шаблоны и вложения <span v-if="localFiles.length || storageFiles.length">· {{ localFiles.length + storageFiles.length }}</span></summary><div class="tool-row"><select v-model="templateId" :disabled="locked" aria-label="Шаблон письма" @focus="!templates.length && fetchTemplates()" @change="applyTemplate"><option value="">{{ templatesLoading ? 'Загрузка…' : 'Выберите шаблон' }}</option><option v-for="template in templates" :key="template.id" :value="template.id">{{ template.name }}</option></select><button :disabled="locked" @click="templatesDialog = true">Управлять шаблонами</button></div><div class="tool-row"><input ref="fileInput" type="file" multiple :disabled="locked" class="file-input" aria-label="Добавить вложения" @change="addFiles"><button :disabled="locked" @click="fileInput?.click()">＋ Локальные файлы</button><span class="muted">Прикладываются при отправке</span></div><div class="attachment-list"><span v-for="(file, index) in localFiles" :key="`${file.name}-${index}`">{{ file.name }} <button :disabled="locked" :aria-label="`Удалить вложение ${file.name}`" @click="localFiles.splice(index, 1)">×</button></span></div><div class="storage-files"><label v-for="file in fileItems" :key="file.path" class="check"><input v-model="storageFiles" :disabled="locked" type="checkbox" :value="file.path">{{ file.name }}</label></div></details>
                    </div>
                    <div class="pane-title line-title"><strong>Товары в заказе · {{ form.items?.length || 0 }}</strong><span>Количество — в единице товара</span></div>
                    <div class="table-wrap"><table class="mac-table selected-table"><thead><tr><th>Товар</th><th class="number">Количество</th><th>Ед.</th><th class="number">Закупочная цена</th><th>Примечание поставщику</th><th></th></tr></thead><tbody><tr v-for="(item, index) in form.items" :key="item.good_id"><td><strong>{{ item.name }}</strong><small>{{ item.quotation_id ? `Предложение №${item.quotation_id}` : 'Цена вручную' }}</small><small>{{ vatLabel(item) }}</small></td><td><input v-model="item.quantity" :disabled="locked" type="number" min="0.000001" step="0.000001" :aria-label="`Количество ${item.name}`"></td><td>{{ item.measurement?.unit_label || '?' }}</td><td><input v-model="item.unit_price" :disabled="locked" type="number" min="0" step="0.0001" placeholder="Уточнить" :aria-label="`Цена ${item.name}`" @input="detachQuotation(item)"><small>{{ item.currency_code || '' }}</small><select v-model="item.currency_id" :disabled="locked" :aria-label="`Валюта ${item.name}`" @change="detachQuotation(item); item.currency_code = context?.currencies?.find(currency => currency.id === Number(item.currency_id))?.code || ''"><option :value="null">Валюта</option><option v-for="currency in context?.currencies || []" :key="currency.id" :value="currency.id">{{ currency.code }}</option></select></td><td><input v-model="item.note" :disabled="locked" maxlength="1000" :aria-label="`Примечание ${item.name}`"></td><td><button :disabled="locked" :aria-label="`Убрать ${item.name}`" @click="form.items.splice(index, 1)">×</button></td></tr><tr v-if="!form.items?.length"><td colspan="6" class="empty">Выберите товары в инструментах справа.</td></tr></tbody></table></div>
                    <label class="internal-note">Внутренняя заметка · не включается в письмо<textarea v-model="form.internal_note" :disabled="locked" rows="2" maxlength="5000"></textarea></label>
